"""v0.2 buyer: complete-cost packages, a price concession schedule and one checked close.

Every accept and walk-away goes through `evaluator.close_decision` (eligible sheets first, then
C with supplier estimates, against the alternative). Our non-price terms stay as offered unless a
supplier package evaluated by C is cheaper than its price for ours. No claims and no model yet.
"""

import logging
import math
import os
import time

from arena_kit.cost import closing_terms, complete_offer, must_haves_ok, total_cost
from arena_kit.docs import standard_terms
from arena_kit.play import latest, live_threads, moves_left

from .evaluator import (
    best_close,
    close_decision,
    eligible_sheets,
    nonprice,
    price_for_cost,
    revealed_deltas,
    same_package,
    supplier_for,
)
from .guards import leaks
from .optimizer import alternative_cost, best_terms

log = logging.getLogger("negotiator")


def standing(case, events, supplier=None):
    """(term_sheet_id, terms) of the cheapest eligible sheet in the supplier's latest message, else
    of its cheapest priced sheet, else (None, {})."""
    cands = eligible_sheets(case, events, supplier, alternatives=True) or _priced(case, events, supplier)
    if cands:
        return cands[0][1], cands[0][2]
    sheets = latest(events).get("term_sheets") or [] if events else []
    return (sheets[0]["term_sheet_id"], sheets[0]["terms"]) if sheets else (None, {})


def _priced(case, events, supplier=None):
    """[(C, sheet_id, terms)] of every priced sheet in the latest message, must-haves ignored."""
    std = standard_terms(events)
    out = []
    for s in latest(events).get("term_sheets") or []:
        c = total_cost(case, s.get("terms") or {}, std, supplier)
        if s.get("term_sheet_id") and math.isfinite(c):
            out.append((c, s["term_sheet_id"], s["terms"]))
    return sorted(out, key=lambda x: (x[0], x[1]))


def load_estimates(case):
    """{supplier_id: estimate} from `dossiers.supplier_estimate` once it exists, else {}."""
    try:
        from .dossiers import supplier_estimate
    except ImportError:
        return {}
    out = {}
    for sid in case.get("suppliers", []):
        try:
            est = supplier_estimate(case, sid)
        except NotImplementedError:
            return {}
        except Exception:
            log.exception("supplier estimate for %s failed; using none", sid)
            continue
        if est:
            out[sid] = est
    return out


def _ceil2(x):
    return math.ceil(round(x * 100, 6)) / 100


class PackageAgent:
    version = "PackageAgent-v0.2"

    def __init__(
        self,
        anchor=0.12,
        rounds=5,
        close_gap=0.005,
        tracer=None,
        estimates=None,
        final_hold_s=40.0,
        meso=None,
        p_walk=0.25,
        claims=None,
        policy=None,
    ):
        self.anchor, self.rounds, self.close_gap, self.tracer = anchor, rounds, close_gap, tracer
        self.policy = policy
        self.package_advisor, self.package_notes = None, {}
        if policy and policy.package_advice_types:
            from .package_advisor import PackageAdvisor

            self.package_advisor = PackageAdvisor()
        self.conditional_exchange = False
        self.trades = None
        if policy:
            from .trades import TradePolicy

            self.trades = TradePolicy(policy, self._log)
        self.meso = os.environ.get("NEGOTIATOR_MESO") == "1" if meso is None else meso
        self.final_hold_s = final_hold_s
        self.p_walk = p_walk  # chance a supplier walks when its final offer is countered (D02: 2 of 9)
        self.claims = os.environ.get("NEGOTIATOR_CLAIMS") == "1" if claims is None else claims
        if policy is not None:
            self.claims = bool(policy.evidence_types)
        self.evidence = None
        if self.claims:
            from .evidence import EvidencePolicy

            self.evidence = EvidencePolicy(tracer=tracer, case_types=policy.evidence_types if policy else None)
        self.prev = {}  # supplier -> non-price terms of our last offer
        self.final_counters = {}  # supplier -> counters sent to its final offers (at most one)
        self.beat_asked = {}  # rival supplier -> final-offer sheet id we asked it to beat
        self.final_seen = {}  # final-offer sheet id -> monotonic time first seen
        if estimates is None and os.environ.get("NEGOTIATOR_ESTIMATES") != "1":
            estimates = {}  # dossier estimates are opt-in until calibrated (docs: experiments/LOG.md)
        self._estimates, self._est_case, self._est_cache = estimates, None, {}

    # -- estimates ----------------------------------------------------------------------------
    def estimates_for(self, case):
        """{supplier_id: estimate}: the injected estimates, else `dossiers.supplier_estimate`
        (with NEGOTIATOR_ESTIMATES=1)."""
        if self._estimates is not None:
            return self._estimates
        if self._est_case != case["case_id"]:
            self._est_case, self._est_cache = case["case_id"], load_estimates(case)
        return self._est_cache

    def _sup(self, case, threads, sid):
        return supplier_for(self.estimates_for(case), sid, standard_terms(threads[sid]))

    # -- helpers ------------------------------------------------------------------------------
    @staticmethod
    def _ours(events):
        return [m["term_sheets"][0]["terms"] for m in events if m.get("from") == "buyer" and m.get("term_sheets")]

    def _log(self, case, kind, sid, **fields):
        if self.tracer:
            self.tracer.log("decision", case=case["case_id"], kind=kind, supplier=sid, **fields)

    def log_close(self, case, threads, decision, reason):
        best = best_close(case, threads, self.estimates_for(case))
        action = decision["message"]["action"]
        fields = {"c_alt": alternative_cost(case), "reason": reason}
        if action["type"] == "accept" and best:
            fields.update(c=best[0], sheet=action["term_sheet_id"])
        self._log(case, action["type"], decision["supplier_id"], **fields)

    def _close(self, case, threads, reason):
        decision = close_decision(case, threads, self.estimates_for(case), reason)
        self.log_close(case, threads, decision, reason)
        return decision

    def _offer(self, case, sid, terms, std, sup, c_alt, reason, variants=()):
        body = (
            f"Thank you for your offer. To go ahead we propose the attached terms: "
            f"unit price EUR {terms['unit_price']:.2f}"
            + "".join(f", {k.replace('_', ' ')} {v}" for k, v in terms.items() if k != "unit_price")
            + ". We look forward to your confirmation."
        )
        if self.trades and case["type"] in self.policy.package_types:
            if "contract_months" in terms:
                body += (
                    f" We offer a {terms['contract_months']}-month commitment"
                    + (
                        f" at annual volume {terms['volume_per_year']};"
                        if "volume_per_year" in terms
                        else " at unchanged annual volume;"
                    )
                    + " please reflect that commitment in your price, with payment priced as part of the package."
                )
            if "ppm_commitment" in terms:
                body += (
                    f" We can accept the proposed future quality commitment of {terms['ppm_commitment']} ppm"
                    " in exchange for the proposed price and chargeback terms."
                )
            body += (
                " This is a conditional exchange: we can commit to this package in return for the proposed unit price."
            )
        elif self.conditional_exchange and any(k != "unit_price" for k in terms):
            body += " The proposed non-price terms are conditional on the proposed unit price as one package."
        assert not leaks(body), "body would leak internal information"
        self.prev[sid] = {k: v for k, v in terms.items() if k != "unit_price"}
        c = total_cost(case, terms, std, sup)
        sheets = [{"terms": t} for t in [terms, *variants][:3]]
        self._log(case, "offer", sid, terms=terms, c=c, c_alt=c_alt, reason=reason, variants=list(variants) or None)
        return {
            "supplier_id": sid,
            "message": {"subject": case["title"], "body": body, "term_sheets": sheets},
        }

    def _payment_variants(self, case, terms, theirs, std, sup):
        """Up to two sheets at our main sheet's C that differ only in payment days (the supplier's
        and the fastest option): the supplier picks the mix it values."""
        options = (case.get("term_options") or {}).get("payment_days") or []
        if "payment_days" not in terms or not options:
            return []
        c_main = total_cost(case, terms, std, sup)
        out = []
        for pay in (theirs.get("payment_days"), min(options)):
            if pay is None or pay == terms["payment_days"] or pay in [v["payment_days"] for v in out]:
                continue
            v = {**terms, "payment_days": pay}
"""Per-supplier dossiers from the data package (and the Sunday release).

A dossier is everything the data says about one supplier, with citable IDs kept:
master data, intel (credit index now vs. 12 m ago, equity, owner type), news (topic-tagged),
notes/letters/e-mails, scorecards, our payment lateness, negotiation history (asked vs. settled),
contracts and clauses, quotes, price conditions, should-cost for its parts.

Loading goes through `arena_kit.data.DataPackage`, so the Sunday release (ARENA_RELEASE or a
`release-sunday` folder in/next to the package) adds its news and letters without code changes.
"""

import os
import weakref
from dataclasses import dataclass, field
from pathlib import Path

from arena_kit.cost import RELATIONSHIP_GOALS
from arena_kit.data import DataPackage

from negotiator import traits as traits_mod

DATA_CANDIDATES = ("data/package", "/tmp/nak/data")
SKIP_SUBJECTS = {"Holiday shutdown", "New contact person", "ISO 9001 certificate", "Packaging",
                 "Trade fair invitation"}

# company.md: full cost relative to the German base for German-base should-cost rows.
COUNTRY_FACTOR = {"DE": 1.0, "AT": 1.05, "CH": 1.05, "CZ": 0.825, "PL": 0.825, "HU": 0.825, "TR": 0.75, "CN": 0.7}
BASE_RATE = 0.08  # company cost of capital; a healthy supplier's usual rate (assumption)
CASH_SHORT_RATE = 0.15
CRISIS_RATE = 0.20
ASSUMED_MARGIN = 0.06  # only without any should-cost row
_BUILT: weakref.WeakKeyDictionary = weakref.WeakKeyDictionary()  # package -> build(package)


def load_package(data_dir=None, release=None) -> DataPackage:
    """The data package plus the Sunday release overlay (`release` or ARENA_RELEASE)."""
    for c in (data_dir, os.environ.get("ARENA_DATA"), *DATA_CANDIDATES):
        if c and (Path(c).expanduser() / "facts.json").is_file():
            return DataPackage(c, release=release)
    raise FileNotFoundError("data package not found: pass data_dir, set ARENA_DATA or run `uv run arena data`")


@dataclass
class Dossier:
    supplier_id: str
    name: str
    country: str
    category: str
    master: dict = field(default_factory=dict)  # suppliers row: payment_days, incoterm, lead time, contract
    intel: dict = field(default_factory=dict)
    news: list[dict] = field(default_factory=list)
    notes: list[dict] = field(default_factory=list)  # {id, date, kind, subject, text}
    scorecard: dict = field(default_factory=dict)
    payment_lateness_days: float | None = None
    history: list[dict] = field(default_factory=list)
    should_cost: dict = field(default_factory=dict)  # part_id -> row
    traits: set[str] = field(default_factory=set)


def _note(package: DataPackage, ref: str, fact: dict) -> dict | None:
    if fact.get("title") in SKIP_SUBJECTS:
        return None
    try:
        text = package.document(ref)
    except (FileNotFoundError, ValueError):
        text = ""
    if text.lstrip().startswith("#"):
        text = text.split("\n", 3)[-1].strip()
    return {"id": ref, "date": fact.get("date"), "kind": fact.get("type"), "subject": fact.get("title"), "text": text}


def build(package) -> dict[str, Dossier]:
    """All detailed suppliers (`suppliers.detail = 'full'`), keyed by `sup:` id."""
    q = package.query
    by_sup_news: dict[str, list] = {}
    by_sup_docs: dict[str, list] = {}
    for ref in package.ids("news:"):
        f = package.lookup(ref) or {}
        by_sup_news.setdefault(f.get("supplier") or f.get("supplier_id"), []).append(
            {"id": ref, "date": f.get("date"), "topic": f.get("topic"), "headline": f.get("headline")})
    for ref in package.ids("doc:"):
        f = package.lookup(ref) or {}
        by_sup_docs.setdefault(f.get("supplier") or f.get("supplier_id"), []).append((ref, f))
    out = {}
    for s in q("SELECT * FROM suppliers WHERE detail = 'full' ORDER BY id", limit=10_000):
        sid = s["id"]
        intel = (q("SELECT * FROM supplier_intel WHERE supplier_id = ?", (sid,)) or [{}])[0]
        sc = (q("SELECT * FROM scorecards WHERE supplier_id = ? ORDER BY quarter DESC LIMIT 1", (sid,)) or [{}])[0]
        late = q("SELECT round(AVG(julianday(paid_date) - julianday(due_date)), 1) d FROM invoices "
                 "WHERE supplier_id = ? AND paid_date IS NOT NULL", (sid,))[0]["d"]
"""Opt-in, deterministic claim decoration; does not change the package policy.

Only single-supplier price-increase cases are enabled for the first experiment.
Reconstruct used IDs from buyer messages after resume. Reserve proposed IDs too:
skipping an unsent claim is preferable to consuming the same fact twice.
"""

from dataclasses import asdict

from .claims import MAX_CHECKED, case_facts, claim_keys, index_relevance, pick, verify
from .context import DATA_ERRORS, build_context, content_hash
from .dossiers import load_package


class EvidencePolicy:
    def __init__(self, package=None, tracer=None, case_types=None):
        self.case_types = set(case_types if case_types is not None else ["price_increase"])
        self.package = package
        self.tracer = tracer
        self.banks = {}
        self.contexts = {}
        self.context_keys = {}
        self.reserved = {}

    def eligible(self, case, move):
        message = move.get("message") or {}
        return (
            case.get("type") in self.case_types
            and len(case.get("suppliers", [])) == 1
            and bool(message.get("term_sheets"))
            and not message.get("action")
        )

    def context_for(self, case):
        """Prepare/cache a snapshot; no selection, reservations or sends."""
        if self.package is None:
            self.package = load_package()
        cid = case["case_id"]
        key = content_hash({"case": case, "facts": self.package.facts})
        if self.context_keys.get(cid) != key:
            context = build_context(case, self.package)
            self.contexts[cid] = context
            self.context_keys[cid] = key
            self.banks[cid] = context.candidates
            if self.tracer:
                self.tracer.log("evidence_context", case=cid, context_version=context.version,
                                context=context.to_dict())
        return self.contexts[cid]

    def fallback(self, case, exc):
        if self.tracer:
            self.tracer.log("evidence_fallback", case=case["case_id"], error_type=type(exc).__name__)

    def enrich(self, case, threads, sid, move, context=None):
        message = move.get("message")
        if not self.eligible(case, move):
            return move
        cid = case["case_id"]
        try:
            context = context if context is not None else self.context_for(case)
            if (
                context.case_id != cid
                or context.supplier_ids != tuple(case.get("suppliers") or [])
                or context.part_ids != tuple(case.get("parts") or [])
            ):
                raise ValueError("context scope mismatch")
            facts = case_facts(case, self.package)
            used = set(self.reserved.get(cid, set()))
            for events in threads.values():
                for event in events:
                    if event.get("from") == "buyer":
                        used.update(event.get("refs") or [])
            existing = set(message.get("refs") or [])
            used.update(existing)
            bank = [c for c in context.candidates if verify(c, facts, self.package, case)]
            priorities, reasons = index_relevance(bank, case, self.package, threads.get(sid, []))
            # Each pre-existing ref conservatively consumes one checked-claim slot.
            budget = max(0, MAX_CHECKED - len(existing))
            chosen = pick(
                bank, used, max_claims=budget, supplier_id=sid,
                case_type="renewal_trade" if case["type"] == "renewal" else case["type"],
                index_priorities=priorities,
            )
        except DATA_ERRORS as exc:
            self.fallback(case, exc)
            return move
        if self.tracer:
            self.tracer.log("evidence_selection", case=cid, supplier=sid, context_version=context.version,
                            index_relevance=reasons, available_slots=budget,
                            selected=[{"kind": c.kind, "ids": list(c.ids)} for c in chosen])
        if not chosen:
            return move
        refs = list(dict.fromkeys([*(message.get("refs") or []), *(i for c in chosen for i in c.ids)]))
        self.reserved.setdefault(cid, set()).update(k for c in chosen for k in claim_keys(c))
        body = message.get("body", "") + "\n\n" + "\n".join(c.sentence for c in chosen)
        if self.tracer:
            self.tracer.log("evidence", case=cid, supplier=sid, context_version=context.version,
                            claims=[asdict(c) for c in chosen])
        return {**move, "message": {**message, "body": body, "refs": refs}}

