def test_fixed_volume_uses_case_scope_and_public_unit_not_private_need():
    c = case()
    c["buyer"]["need_per_year"] = 999999
    sentence = fixed_scope(c, {"contract_months": 24}, Package())
    assert "23700 kg per year for 24 months" in sentence
    assert "999999" not in sentence and "higher" not in sentence
    c["negotiable"].append("volume_per_year")
    assert fixed_scope(c, {"contract_months": 24}, Package()) is None


def test_no_invented_unit_volume_or_duration():
    c = case()
    assert fixed_scope(c, {}, Package()) is None
    c["fixed_terms"].pop("volume_per_year")
    assert fixed_scope(c, {"contract_months": 24}, Package()) is None


def test_post_advice_scope_preserves_terms_and_close(monkeypatch):
    c = case()
    terms = {"unit_price": 5.24, "contract_months": 24, "payment_days": 30, "index_clause": None}
    move = {"supplier_id": c["suppliers"][0], "message": {
        "body": "Conditional package.", "term_sheets": [{"terms": terms}], "refs": []}}
    before = copy.deepcopy(move)
    monkeypatch.setattr(PackageAgent, "decide", lambda *_: move)
    monkeypatch.setattr("negotiator.scope_agent.load_package", Package)
    selected = FixedScopeAgent().decide(c, {})
    assert selected["message"]["term_sheets"] == move["message"]["term_sheets"]
    assert "23700 kg per year for 24 months" in selected["message"]["body"]
    assert move == before
    move["message"] = {"action": {"type": "accept", "term_sheet_id": "offer:1"}}
    assert FixedScopeAgent().decide(c, {}) is move

